        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>DANIEL G</strong> od is my judge, or judge of God. (1.) David’s second son, “born unto him in Hebron, of Abigail the Carmelitess” (1 Chronicles 3:1). He is called also Chileab (2 Samuel 3:3). (2.) One of the four great prophets, although he is not once spoken of in the Old Testament as a prophet. His life and prophecies are recorded in the Book of Daniel. He was descended from one of the noble families of Judah (Daniel 1:3), and was probably born in Jerusalem about B.C. 623, during the reign… <em>[Reviewer: condense Easton's entry as needed.]</em>",
