        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BATH-SHEBA</strong> daughter of the oath, or of seven, called also Bath-shu’a (1 Chronicles 3:5), was the daughter of Eliam (2 Samuel 11:3) or Ammiel (1 Chronicles 3:5), and wife of Uriah the Hittite. David committed adultery with her (2 Samuel 11:4, 5; Psalm 51:1). The child born in adultery died (2 Samuel 12:15-19). After her husband was slain (11:15) she was married to David (11:27), and became the mother of Solomon (12:24; 1 Kings 1:11; 2:13). She took a prominent part in securing the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
