        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>CHRONICLES</strong> , BOOKS OF The two books were originally one. They bore the title in the Massoretic Hebrew Dibre hayyamim, i.e., “Acts of the Days.” This title was rendered by Jerome in his Latin version “Chronicon,” and hence “Chronicles.” In the Septuagint version the book is divided into two, and bears the title Paraleipomena, i.e., “things omitted,” or “supplements”, because containing many things omitted in the Books of Kings. The contents of these books are comprehended under four… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
