        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>OPHRAH</strong> a fawn. 1 Chronicles 4:14. (1.) A city of Benjamin (Joshua 18:23); probably identical with Ephron (2 Chronicles 13:19) and Ephraim (John 11:54). (2.) “Of the Abi-ezrites.” A city of Manasseh, 6 miles south-west of Shechem, the residence of Gideon (Judges 6:11; 8:27, 32). After his great victory over the Midianites, he slew at this place the captive kings (8:18-21). He then assumed the function of high priest, and sought to make Ophrah what Shiloh should have been. This thing… <em>[Reviewer: condense Easton's entry as needed.]</em>",
