        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ETAM</strong> eyrie. (1.) A village of the tribe of Simeon (1 Chronicles 4:32). Into some cleft (“top,” A.V.,; R.V., “cleft”) of a rock here Samson retired after his slaughter of the Philistines (Judges 15:8, 11). It was a natural stronghold. It has been identified with Beit ‘Atab, west of Bethlehem, near Zorah and Eshtaol. On the crest of a rocky knoll, under the village, is a long tunnel, which may be the “cleft” in which Samson hid. (2.) A city of Judah, fortified by Rehoboam (2… <em>[Reviewer: condense Easton's entry as needed.]</em>",
