        "<strong>Dictionary (Easton's).</strong> <strong>GOG</strong> (1.) A Reubenite (1 Chronicles 5:4), the father of Shimei. (2.) The name of the leader of the hostile party described in Ezekiel 38,39, as coming from the “north country” and assailing the people of Israel to their own destruction. This prophecy has been regarded as fulfilled in the conflicts of the Maccabees with Antiochus, the invasion and overthrow of the Chaldeans, and the temporary successes and destined overthrow of the Turks. But “all these interpretations are… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
