        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BAAL-HERMON L</strong> ord of Hermon. (1.) A city near Mount Hermon inhabited by the Ephraimites (1 Chronicles 5:23). Probably identical with Baal-gad (Joshua 11:17). (2.) A mountain east of Lebanon (Judges 3:3). Probably it may be the same as Mount Hermon, or one of its three peaks. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
