        "<strong>Dictionary (Easton's).</strong> <strong>HABOR</strong> the united stream, or, according to others, with beautiful banks, the name of a river in Assyria, and also of the district through which it flowed (1 Chronicles 5:26). There is a river called Khabur which rises in the central highlands of Kurdistan, and flows south-west till it falls into the Tigris, about 70 miles above Mosul. This was not, however, the Habor of Scripture. There is another river of the same name (the Chaboras) which, after a course of about 200 miles, flows… <em>[Reviewer: condense Easton's entry as needed.]</em>",
