        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ITHAMAR</strong> palm isle, the fourth and youngest son of Aaron (1 Chronicles 6:3). He was consecrated to the priesthood along with his brothers (Exodus 6:23); and after the death of Nadab and Abihu, he and Eleazar alone discharged the functions of that office (Leviticus 10:6, 12; Numbers 3:4). He and his family occupied the position of common priest till the high priesthood passed into his family in the person of Eli (1 Kings 2:27), the reasons for which are not recorded. (See ZADOK.) <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
