        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AMAZIAH</strong> strengthened by Jehovah. (1.) A Levite, son of Hilkiah, of the descendants of Ethan the Merarite (1 Chronicles 6:45). (2.) The son and successor of Joash, and eighth king of the separate kingdom of Judah (2 Kings 14:1-4). He began his reign by punishing the murderers of his father (5-7; 2 Chronicles 25:3-5). He was the first to employ a mercenary army of 100,000 Israelite soldiers, which he did in his attempt to bring the Edomites again under the yoke of Judah (2 Chronicles… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
