        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>KIRJATHAIM</strong> two cities; a double city. (1.) A city of refuge in Naphtali (1 Chronicles 6:76). (2.) A town on the east of Jordan (Genesis 14:5; Deuteronomy 2:9, 10). It was assigned to the tribe of Reuben (Numbers 32:37). In the time of Ezekiel (25:9) it was one of the four cities which formed the “glory of Moab” (comp. Jeremiah 48:1, 23). It has been identified with el-Kureiyat, 11 miles south-west of Medeba, on the south slope of Jebel Attarus, the ancient Ataroth. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
