        "<strong>Dictionary (Easton's).</strong> <strong>JEDIAEL</strong> known by God. (1.) One of the sons of Benjamin, whose descendants numbered 17,200 warriors (1 Chronicles 7:6, 10, 11). (2.) A Shimrite, one of David’s bodyguard (1 Chronicles 11:45). Probably same as in 12:20. (3.) A Korhite of the family of Ebiasaph, and one of the gate-keepers to the temple (1 Chronicles 26:2). <em>[Reviewer: condense Easton's entry as needed.]</em>",
