        "<strong>Dictionary (Easton's).</strong> <strong>JERIMOTH</strong> heights. (1.) One of the sons of Bela (1 Chronicles 7:7). (2.) 1 Chronicles 24:30, a Merarite Levite. (3.) A Benjamite slinger who joined David at Ziklag (1 Chronicles 12:5). (4.) A Levitical musician under Heman his father (1 Chronicles 25:4). (5.) 1 Chronicles 27:19, ruler of Naphtali. (6.) One of David’s sons (2 Chronicles 11:18). (7.) A Levite, one of the overseers of the temple offerings (2 Chronicles 31:13) in the reign of Hezekiah. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
