        "<strong>Dictionary (Easton's).</strong> <strong>ABIEEZER</strong> father of help; i.e., “helpful.” (1.) The second of the three sons of Hammoleketh, the sister of Gilead. He was the grandson of Manasseh (1 Chronicles 7:18). From his family Gideon sprang (Joshua 17:2; comp. Judges 6:34; 8:2). He was also called Jeezer (Numbers 26:30). (2.) One of David’s thirty warriors (2 Samuel 23:27; comp. 1 Chronicles 27:12). (3.) The prince of the tribe of Dan at the Exodus (Numbers 1:12). <em>[Reviewer: condense Easton's entry as needed.]</em>",
