        "<strong>Dictionary (Easton's).</strong> <strong>ABIHUD</strong> father (i.e., “possessor”) of renown. (1.) One of the sons of Bela, the son of Benjamin (1 Chronicles 8:3); called also Ahihud (ver. 7). (2.) A descendant of Zerubbabel and father of Eliakim (Matthew 1:13, “Abiud”); called also Juda (Luke 3:26), and Obadiah (1 Chronicles 3:21). <em>[Reviewer: condense Easton's entry as needed.]</em>",
