        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AHIHUD</strong> brother (i.e., “friend”) of union. (1.) A son of Bela, the son of Benjamin (1 Chronicles 8:7). (2.) Name different in Hebrew, meaning brother of Judah. Chief of the tribe of Asher; one of those appointed by Moses to superintend the division of Canaan among the tribe (Numbers 34:27). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
