        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AHIJAH</strong> brother (i.e., “friend”) of Jehovah. (1.) One of the sons of Bela (1 Chronicles 8:7, R.V.). In A.V. called “Ahiah.” (2.) One of the five sons of Jerahmeel, who was great-grandson of Judah (1 Chronicles 2:25). (3.) Son of Ahitub (1 Samuel 14:3, 18), Ichabod’s brother; the same probably as Ahimelech, who was high priest at Nob in the reign of Saul (1 Samuel 22:11). Some, however, suppose that Ahimelech was the brother of Ahijah, and that they both officiated as high priests,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
