        "<strong>Dictionary (Easton's).</strong> <strong>AHIO</strong> brotherly. (1.) One of the sons of Beriah (1 Chronicles 8:14). (2.) One of the sons of Jehiel the Gibeonite (1 Chronicles 8:31; 9:37). (3.) One of the sons of Abinadab the Levite. While Uzzah went by the side of the ark, he walked before it guiding the oxen which drew the cart on which it was carried, after having brought it from his father’s house in Gibeah (1 Chronicles 13:7; 2 Samuel 6:3, 4). <em>[Reviewer: condense Easton's entry as needed.]</em>",
