        "<strong>Dictionary (Easton's).</strong> <strong>ESHBAAL</strong> man of Baal, the fourth son of king Saul (1 Chronicles 8:33; 9:39). He is also called Ish-bosheth (q.v.), 2 Samuel 2:8. <em>[Reviewer: condense Easton's entry as needed.]</em>",
