        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>NER</strong> light, the father of Kish (1 Chronicles 8:33). 1 Samuel 14:51 should be read, “Kish, the father of Saul, and Ner, the father of Abner, were the sons of Abiel.” And hence this Kish and Ner were brothers, and Saul and Abner were first cousins (comp. 1 Chronicles 9:36). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
