        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>MICAH</strong> a shortened form of Micaiah, who is like Jehovah? (1.) A man of Mount Ephraim, whose history so far is introduced in Judges 17, apparently for the purpose of leading to an account of the settlement of the tribe of Dan in Northern Palestine, and for the purpose also of illustrating the lawlessness of the times in which he lived (Judges 18; 19:1-29; 21:25). (2.) The son of Merib-baal (Mephibosheth), 1 Chronicles 8:34, 35. (3.) The first in rank of the priests of the family of… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
