        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AHAZ</strong> possessor. (1.) A grandson of Jonathan (1 Chronicles 8:35; 9:42). (2.) The son and successor of Jotham, king of Judah (2 Kings 16; Isaiah 7-9; 2 Chronicles 28). He gave himself up to a life of wickedness and idolatry. Notwithstanding the remonstrances and warnings of Isaiah, Hosea, and Micah, he appealed for help against Rezin, king of Damascus, and Pekah, king of Israel, who threatened Jerusalem, to Tiglath-pileser, the king of Assyria, to the great injury of his kingdom… <em>[Reviewer: condense Easton's entry as needed.]</em>",
