        "<strong>Dictionary (Easton's).</strong> <strong>MATTITHIAH</strong> gift of Jehovah. (1.) One of the sons of Jeduthun (1 Chronicles 25:3, 21). (2.) The eldest son of Shallum, of the family of Korah (1 Chronicles 9:31). (3.) One who stood by Ezra while reading the law (Nehemiah 8:4). (4.) The son of Amos, and father of Joseph, in the genealogy of our Lord (Luke 3:25). <em>[Reviewer: condense Easton's entry as needed.]</em>",
