        "<strong>Dictionary (Easton's).</strong> <strong>JASHOBEAM</strong> dweller among the people; or to whom the people turn, the Hachmonite (1 Chronicles 11:11), one of David’s chief heroes who joined him at Ziklag (12:6). He was the first of the three who broke through the host of the Philistines to fetch water to David from the well of Bethlehem (2 Samuel 23:13-17). He is also called Adino the Eznite (8). <em>[Reviewer: condense Easton's entry as needed.]</em>",
