        "<strong>Dictionary (Easton's).</strong> <strong>SIBBECAI</strong> the Lord sustains, one of David’s heroes (1 Chronicles 11:29), general of the eighth division of the army (27:11). He slew the giant Saph in the battle of Gob (2 Samuel 21:18; R.V., “Sibbechai”). Called also Mebunnai (23:27). <em>[Reviewer: condense Easton's entry as needed.]</em>",
