        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ZALMON</strong> shady. (1.) One of David’s warriors, called the Ahohite (2 Samuel 23:28); called also Ilai (1 Chronicles 11:29). (2.) A wood near Shechem, from which Abimelech and his party brought boughs and “put them to the hold” of Shechem, “and set the hold on fire” (Judges 9:48). Probably the southern peak of Gerizim, now called Jebel Sulman. (See SALMON.) <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
