        "<strong>Dictionary (Easton's).</strong> <strong>CARPENTER</strong> an artificer in stone, iron, and copper, as well as in wood (2 Samuel 5:11; 1 Chronicles 14:1; Mark 6:3). The tools used by carpenters are mentioned in 1 Samuel 13:19, 20; Judges 4:21; Isaiah 10:15; 44:13. It was said of our Lord, “Is not this the carpenter’s son?” (Matthew 13:55); also, “Is not this the carpenter?” (Mark 6:3). Every Jew, even the rabbis, learned some handicraft: Paul was a tentmaker. “In the cities the carpenters would be Greeks, and skilled workmen; the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
