        "<strong>Dictionary (Easton's).</strong> <strong>MAASEIAH</strong> the work of Jehovah. (1.) One of the Levites whom David appointed as porter for the ark (1 Chronicles 15:18, 20). (2.) One of the “captains of hundreds” associated with Jehoiada in restoring king Jehoash to the throne (2 Chronicles 23:1). (3.) The “king’s son,” probably one of the sons of king Ahaz, killed by Zichri in the invasion of Judah by Pekah, king of Israel (2 Chronicles 28:7). (4.) One who was sent by king Josiah to repair the temple (2 Chronicles 34:8). He was… <em>[Reviewer: condense Easton's entry as needed.]</em>",
