        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>CORNET H</strong> ebrews shophar, “brightness,” with reference to the clearness of its sound (1 Chronicles 15:28; 2 Chronicles 15:14; Psalm 98:6; Hos. 5:8). It is usually rendered in the Authorized Version “trumpet.” It denotes the long and straight horn, about eighteen inches long. The words of Joel, “Blow the trumpet,” literally, “Sound the cornet,” refer to the festival which was the preparation for the day of Atonement. In Daniel 3:5, 7, 10, 15, the word (keren) so rendered is a curved… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
