        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JEIEL</strong> snatched away by God. (1.) A descendant of Benjamin (1 Chronicles 9:35; 8:29). (2.) One of the Levites who took part in praising God on the removal of the ark to Jerusalem (1 Chronicles 16:5). (3.) 2 Chronicles 29:13. A Levite of the sons of Asaph. (4.) 2 Chronicles 26:11. A scribe. (5.) 1 Chronicles 5:7. A Reubenite chief. (6.) One of the chief Levites, who made an offering for the restoration of the Passover by Josiah (2 Chronicles 35:9). (7.) Ezra 8:13. (8.) Ezra 10:43. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
