        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JEDUTHUN</strong> lauder; praising, a Levite of the family of Merari, and one of the three masters of music appointed by David (1 Chronicles 16:41, 42; 25:1-6). He is called in 2 Chronicles 35:15 “the king’s seer.” His descendants are mentioned as singers and players on instruments (Nehemiah 11:17). He was probably the same as Ethan (1 Chronicles 15:17, 19). In the superscriptions to Psalm 39, 62, and 77, the words “upon Jeduthun” probably denote a musical instrument; or they may denote the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
