        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>NUMBERING OF THE PEOPLE B</strong> esides the numbering of the tribes mentioned in the history of the wanderings in the wilderness, we have an account of a general census of the whole nation from Dan to Beersheba, which David gave directions to Joab to make (1 Chronicles 21:1). Joab very reluctantly began to carry out the king’s command. This act of David in ordering a numbering of the people arose from pride and a self-glorifying spirit. It indicated a reliance on his part on an arm of flesh, an estimating… <em>[Reviewer: condense Easton's entry as needed.]</em>",
