        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ARAUNAH</strong> agile; also called Ornan 1 Chronicles 21:15, a Jebusite who dwelt in Jerusalem before it was taken by the Israelites. The destroying angel, sent to punish David for his vanity in taking a census of the people, was stayed in his work of destruction near a threshing-floor belonging to Araunah which was situated on Mount Moriah. Araunah offered it to David as a free gift, together with the oxen and the threshing instruments; but the king insisted on purchasing it at its full… <em>[Reviewer: condense Easton's entry as needed.]</em>",
