        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>PROSELYTE</strong> is used in the LXX. for “stranger” (1 Chronicles 22:2), i.e., a comer to Palestine; a sojourner in the land (Exodus 12:48; 20:10; 22:21), and in the New Testament for a convert to Judaism. There were such converts from early times (Isaiah 56:3; Nehemiah 10:28; Esther 8:17). The law of Moses made specific regulations regarding the admission into the Jewish church of such as were not born Israelites (Exodus 20:10; 23:12; 12:19, 48; Deuteronomy 5:14; 16:11, 14, etc.). The… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
