        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>SOLOMON</strong> peaceful, (Hebrews Shelomoh), David’s second son by Bathsheba, i.e., the first after their legal marriage (2 Samuel 12). He was probably born about B.C. 1035 (1 Chronicles 22:5; 29:1). He succeeded his father on the throne in early manhood, probably about sixteen or eighteen years of age. Nathan, to whom his education was intrusted, called him Jedidiah, i.e., “beloved of the Lord” (2 Samuel 12:24, 25). He was the first king of Israel “born in the purple.” His father chose… <em>[Reviewer: condense Easton's entry as needed.]</em>",
