        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>SHEBUEL</strong> captive of God. (1.) One of the descendants of Gershom, who had charge of the temple treasures in the time of David (1 Chronicles 23:16; 26:24). (2.) One of the sons of Heman; one of those whose duty it was to “lift up the horn” in the temple service (1 Chronicles 25:4, 5); called also Shubael (ver. 20). <em>[Reviewer: condense Easton's entry as needed.]</em>",
