        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JAHAZIEL</strong> beheld by God. (1.) The third son of Hebron (1 Chronicles 23:19). (2.) A Benjamite chief who joined David at Ziklag (1 Chronicles 12:4). (3.) A priest who accompanied the removal of the ark to Jerusalem (1 Chronicles 16:6). (4.) The son of Zechariah, a Levite of the family of Asaph (2 Chronicles 20:14-17). He encouraged Jehoshaphat against the Moabites and Ammonites. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
