        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>KISH</strong> a bow. (1.) A Levite of the family of Merari (1 Chronicles 23:21; 24:29). (2.) A Benjamite of Jerusalem (1 Chronicles 8:30; 9:36). (3.) A Levite in the time of Hezekiah (2 Chronicles 29:12). (4.) The great-grandfather of Mordecai (Esther 2:5). (5.) A Benjamite, the son of Abiel, and father of king Saul (1 Samuel 9:1, 3; 10:11, 21; 14:51; 2 Samuel 21:14). All that is recorded of him is that he sent his son Saul in search of his asses that had strayed, and that he was buried… <em>[Reviewer: condense Easton's entry as needed.]</em>",
