        "<strong>Dictionary (Easton's).</strong> <strong>JOHN THE BAPTIST</strong> the “forerunner of our Lord.” We have but fragmentary and imperfect accounts of him in the Gospels. He was of priestly descent. His father, Zacharias, was a priest of the course of Abia (1 Chronicles 24:10), and his mother, Elisabeth, was of the daughters of Aaron (Luke 1:5). The mission of John was the subject of prophecy (Matthew 3:3; Isaiah 40:3; Malachi 3:1). His birth, which took place six months before that of Jesus, was foretold by an angel. Zacharias, deprived of the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
