        "<strong>Dictionary (Easton's).</strong> <strong>ELIASHIB</strong> whom God will restore. (1.) A priest, head of one of the courses of the priests of the time of David (1 Chronicles 24:12). (2.) A high priest in the time of Ezra and Nehemiah (Nehemiah 12:22, 23). He rebuilt the eastern city wall (3:1), his own mansion being in that quarter, on the ridge Ophel (3:20, 21). His indulgence of Tobiah the Ammonite provoked the indignation of Nehemiah (13:4, 7). <em>[Reviewer: condense Easton's entry as needed.]</em>",
