        "<strong>Dictionary (Easton's).</strong> <strong>HANANI G</strong> od has gratified me, or is gracious. (1.) One of the sons of Heman (1 Chronicles 25:4, 25). (2.) A prophet who was sent to rebuke king Asa for entering into a league with Benhadad I., king of Syria, against Judah (2 Chronicles 16:1-10). He was probably the father of the prophet Jehu (1 Kings 16:7). (3.) Probably a brother of Nehemiah (Nehemiah 1:2; 7:2), who reported to him the melancholy condition of Jerusalem. Nehemiah afterwards appointed him to have charge of the city… <em>[Reviewer: condense Easton's entry as needed.]</em>",
