        "<strong>Dictionary (Easton's).</strong> <strong>MATTANIAH</strong> gift of Jehovah. (1.) A Levite, son of Heman, the chief of the ninth class of temple singers (1 Chronicles 25:4, 16). (2.) A Levite who assisted in purifying the temple at the reformation under Hezekiah (2 Chronicles 29:13). (3.) The original name of Zedekiah (q.v.), the last of the kings of Judah (2 Kings 24:17). He was the third son of Josiah, who fell at Megiddo. He succeeded his nephew Jehoiakin. <em>[Reviewer: condense Easton's entry as needed.]</em>",
