        "<strong>Dictionary (Easton's).</strong> <strong>OBED-EDOM</strong> servant of Edom. (1.) “The Gittite” (probably so called because he was a native of Gath-rimmon), a Levite of the family of the Korhites (1 Chronicles 26:1, 4-8), to whom was specially intrusted the custody of the ark (1 Chronicles 15:18). When David was bringing up the ark “from the house of Abinadab, that was in Gibeah” (probably some hill or eminence near Kirjath-jearim), and had reached Nachon’s threshing-floor, he became afraid because of the “breach upon Uzzah,” and… <em>[Reviewer: condense Easton's entry as needed.]</em>",
