        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JOAH J</strong> ehovah his brother; i.e., helper. (1.) One of the sons of Obed-edom (1 Chronicles 26:4), a Korhite porter. (2.) A Levite of the family of Gershom (1 Chronicles 6:21), probably the same as Ethan (42). (3.) The son of Asaph, and “recorder” (q.v.) or chronicler to King Hezekiah (2 Kings 18:18, 26, 37). (4.) Son of Joahaz, and “recorder” (q.v.) or keeper of the state archives under King Josiah (2 Chronicles 34:8). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
