        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>FENCED CITIES T</strong> here were in Palestine (1) cities, (2) unwalled villages, and (3) villages with castles or towers (1 Chronicles 27:25). Cities, so called, had walls, and were thus fenced. The fortifications consisted of one or two walls, on which were towers or parapets at regular intervals (2 Chronicles 32:5; Jeremiah 31:38). Around ancient Jerusalem were three walls, on one of which were ninety towers, on the second fourteen, and on the third sixty. The tower of Hananeel, near the… <em>[Reviewer: condense Easton's entry as needed.]</em>",
