        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>DARIC</strong> in the Revised Version of 1 Chronicles 29:7; Ezra 2:69; 8:27; Nehemiah 7:70-72, where the Authorized Version has “dram.” It is the rendering of the Hebrew darkemon and the Greek dareikos. It was a gold coin, bearing the figure of a Persian King with his crown and armed with bow and arrow. It was current among the Jews after their return from Babylon, i.e., while under the Persian domination. It weighed about 128 grains troy, and was of the value of about one guinea or rather… <em>[Reviewer: condense Easton's entry as needed.]</em>",
